const defaults = {
  asofdate: null,
  securitytype: ['Kartik', 'Akira'],
  marketSector: ['Sandhya', 'Atharva'],
  numberofdays: 20,
  marketcaplowerlimit: 250000,
  sharefloat: 0.7,
  operator: 'OR',
  httpBodies: {
    market: {
      filters: {},
      groups: [
        { attribute_code: 'marketSector', value: { eq: 'Equity', type: 'text' } }
      ],
      logic: 'OR'
    },
    equity: {
      filters: { company_ids: [] },
      groups: [
        { attribute_code: 'securitytype', value: { eq: 'ETF', type: 'text' } }
      ],
      logic: 'AND'
    }
  }
};

function deepMerge(target, source) {
  for (const key in source) {
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      if (!target[key]) target[key] = {};
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

return items.map(item => {
  const inputBody = item.json.body || {};
  let output = JSON.parse(JSON.stringify(defaults)); // deep copy

  output = deepMerge(output, inputBody);

  // Use current date for asofdate if not provided
  if (!output.asofdate) {
    output.asofdate = new Date().toISOString().slice(0, 10);
  }

  // Set items_asofdate and asOf for market
  output.httpBodies.market.items_asofdate = output.asofdate;
  if (output.httpBodies.market.groups) {
    output.httpBodies.market.groups.forEach(g => g.asOf = output.asofdate);
  }

  // Set items_asofdate and asOf for equity
  output.httpBodies.equity.items_asofdate = output.asofdate;
  if (output.httpBodies.equity.groups) {
    output.httpBodies.equity.groups.forEach(g => g.asOf = output.asofdate);
  }

  item.json = output;
  return item;
});
